inline const char *NDSIdentifier() {
  return "$NDS";
}

inline bool NDSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, NDSIdentifier());
}

inline bool SizePrefixedNDSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, NDSIdentifier(), true);
}

template <bool B = false>
inline bool VerifyNDSBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<NDS>(NDSIdentifier());
}

